private static object? NormalizeFieldWriteValue(object? value, string field)
{
    if (value is null) return null;
    if (value is JsonElement je)
    {
        return je.ValueKind switch
        {
            JsonValueKind.Null => null,
            JsonValueKind.String => je.GetString(),
            JsonValueKind.True or JsonValueKind.False => je.GetBoolean(),
            JsonValueKind.Number => je.TryGetInt64(out var l) ? (object)l
                : je.TryGetDecimal(out var d) ? d
                : je.GetDouble(),
            _ => throw new LacerteSDKError(SyntheticStatusCodes.FieldWriteInvalid,
                new Dictionary<string, object?> {
                    ["field"] = field,
                    ["clrType"] = $"JsonElement({je.ValueKind})",
                    ["reason"] = "value must be a JSON scalar (string/number/bool/null); arrays and objects are not accepted.",
                })
        };
    }
    // Whitelist scalar CLR types.
    switch (value)
    {
        case string: case bool:
        case sbyte: case byte: case short: case ushort:
        case int: case uint: case long: case ulong:
        case float: case double: case decimal:
        case DateTime: case DateTimeOffset:
            return value;
        default:
            throw new LacerteSDKError(SyntheticStatusCodes.FieldWriteInvalid,
                new Dictionary<string, object?> {
                    ["field"] = field,
                    ["clrType"] = value.GetType().FullName ?? "<unknown>",
                    ["reason"] = "value must be a JSON-serializable scalar.",
                });
    }
}
```

